CREATE POLICY "branding_read_authenticated" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'branding');
CREATE POLICY "branding_insert_staff" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'branding' AND public.is_staff(auth.uid()));
CREATE POLICY "branding_update_staff" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'branding' AND public.is_staff(auth.uid())) WITH CHECK (bucket_id = 'branding' AND public.is_staff(auth.uid()));
CREATE POLICY "branding_delete_staff" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'branding' AND public.is_staff(auth.uid()));